<span class="line"><span style="color:#56B6C2;">    echo</span><span style="color:#98C379;"> &quot;用法: </span><span style="color:#E06C75;font-style:italic;">$0</span><span style="color:#98C379;"> [master|slave-a|slave-b]&quot;</span></span>
