<span class="line"><span style="color:#E5C07B;">        config</span><span style="color:#ABB2BF;">.</span><span style="color:#E5C07B;">EndPoints</span><span style="color:#ABB2BF;">.</span><span style="color:#61AFEF;">Add</span><span style="color:#ABB2BF;">(</span><span style="color:#98C379;">&quot;10.0.1.1&quot;</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">26379</span><span style="color:#ABB2BF;">);</span></span>
