<span class="line"><span style="color:#E5C07B;">            System</span><span style="color:#ABB2BF;">.</span><span style="color:#E5C07B;">out</span><span style="color:#ABB2BF;">.</span><span style="color:#61AFEF;">println</span><span style="color:#ABB2BF;">(</span><span style="color:#98C379;">&quot;Current master: &quot;</span><span style="color:#56B6C2;"> +</span><span style="color:#ABB2BF;"> masterAddr);</span></span>
